import type { RootState } from './state.js'
import { values } from './normalized.js'

/**
 * Upgrade the original HEW invoice-number configuration without overwriting a
 * format the administrator has already customized. Existing issued invoices
 * remain immutable; only future autogenerated numbers use the new format.
 */
export function migrateLegacyHewInvoiceNumbering(state: RootState): boolean {
  let changed = false
  const hewUnits = values(state.masters.units).filter((unit) => {
    const code = unit.code.trim().toUpperCase()
    return code === 'HEW' || code === 'HEW-BW'
  })
  for (const hew of hewUnits) {
    if (hew.invoiceFormat === '{seq}/{FY}') {
      hew.invoiceFormat = 'HEW/{FY}/{seq}'
      changed = true
    }
    if (hew.seqPad < 3) {
      hew.seqPad = 3
      changed = true
    }
  }
  return changed
}
